from typing import List

def calculate_minimum_cost(N: int, S: str, C: List[int]) -> int:
    min_cost = float('inf')

    for i in range(N - 1):
        if S[i] != S[i + 1]:
            # Calculate the cost of making S[i] and S[i+1] the same
            cost = min(C[i], C[i + 1])
            min_cost = min(min_cost, cost)

    return min_cost
